  "a chest drain is confirmed to be correctly positioned (or is inserted first), and a chest x-ray confirms the lung has re-expanded. local anaesthetic (e.g. lidocaine) is instilled through the drain into the pleural space to reduce discomfort. the sclerosing agent mixed with saline is instilled through the drain. the drain is clamped for a period and the patient may be repositioned to spread the agent across the pleural surfaces. the drain is unclamped and left on drainage/suction; it is removed once output is low and a chest x-ray is satisfactory.": "يُتأكد من أن أنبوب تصريف الصدر في موضعه الصحيح (أو يُدخل أولًا)، وتؤكد صورة أشعة الصدر أن الرئة تمددت مجددًا. يُحقن مخدر موضعي (مثل الليدوكائين) عبر الأنبوب في الحيز الجنبي لتقليل الانزعاج. ثم تُحقن المادة المصلّبة الممزوجة بمحلول ملحي عبر الأنبوب. يُغلق الأنبوب فترة من الوقت وقد يُغيَّر وضع المريض لنشر المادة على أسطح الجنبة. ثم يُفتح الأنبوب ويُترك على التصريف / الشفط، ويُزال عندما يقل الناتج وتكون صورة الأشعة مُرضية.",
