  "an error occurred while updating the session": "حدث خطأ أثناء تحديث الجلسة",
  "an inferior vena cava (ivc) filter is a small cage-like device inserted into the inferior vena cava to prevent pulmonary embolism. the procedure is performed under fluoroscopic guidance using local anaesthesia with or without sedation and typically takes 30–60 minutes. step-by-step procedure includes venous access, catheter insertion, positioning, deployment, and post-procedure monitoring.": "مرشح الوريد الأجوف السفلي (IVC) جهاز صغير يشبه القفص يُدخل في الوريد الأجوف السفلي لمنع الانصمام الرئوي. يُجرى الإجراء بتوجيه التنظير الفلوري تحت تخدير موضعي مع تهدئة أو بدونها ويستغرق عادةً 30–60 دقيقة. وتشمل خطواته: المدخل الوريدي، وإدخال القسطرة، وتحديد الموضع، ونشر المرشح، والمراقبة بعد الإجراء.",
  "an inferior vena cava (ivc) filter is a small, cage-like medical device made of metal (usually nitinol or stainless steel) that is inserted into the inferior vena cava — the large vein that carries blood from the lower body back to the heart. its purpose is to catch blood clots (thrombus) that break away from the deep veins of the legs or pelvis before they can travel to the lungs and cause a potentially fatal pulmonary embolism (pe).": "مرشح الوريد الأجوف السفلي (IVC) جهاز طبي صغير يشبه القفص مصنوع من المعدن (عادةً النيتينول أو الفولاذ المقاوم للصدأ) يُدخل في الوريد الأجوف السفلي — وهو الوريد الكبير الذي ينقل الدم من الجزء السفلي من الجسم إلى القلب. والغرض منه التقاط الجلطات الدموية التي تنفصل من الأوردة العميقة في الساقين أو الحوض قبل وصولها إلى الرئتين وتسببها في انصمام رئوي قد يكون مميتًا.",
