  "anaesthesia will be discussed and provided by the anaesthetist. general anaesthesia with cardiopulmonary bypass is planned. for children, drug doses and fluid/blood volumes are weight-based and are calculated and counter-signed on the gsh paediatric weight-based calculation & safety worksheet before surgery. anaesthesia carries its own risks, explained by the anaesthetist, who obtains separate anaesthetic consent and records it separately.": "سيناقش طبيب التخدير التخدير ويقدّمه. من المخطط إجراء تخدير عام مع المجازة القلبية الرئوية. للأطفال، تُحسب جرعات الأدوية وأحجام السوائل والدم حسب الوزن ويُوقّع عليها في ورقة GSH لحساب الجرعات حسب الوزن والسلامة للأطفال قبل الجراحة. للتخدير مخاطره الخاصة التي يشرحها طبيب التخدير، والذي يحصل على موافقة تخدير منفصلة ويسجّلها بشكل مستقل.",
