  "close vitals monitoring: watch bp, spo₂, and chest signs": "مراقبة دقيقة للعلامات الحيوية: راقب ضغط الدم وتشبع الأكسجين وعلامات الصدر",
  "close vitals observations & fluid balance": "مراقبة دقيقة للعلامات الحيوية وتوازن السوائل",
  "close window": "إغلاق النافذة",
  "closing the asds and the pda removes the extra blood flow overloading the right heart and lungs, improves growth, feeding and exercise tolerance, and reduces the long-term risks of heart rhythm problems, raised lung-artery pressure (pulmonary hypertension), heart failure, stroke from clots crossing a defect, and infection of the heart or vessel.": "يؤدي إغلاق عيوب الحاجز الأذيني والقناة الشريانية إلى إزالة تدفق الدم الزائد الذي يُثقل الجانب الأيمن من القلب والرئتين، ويحسّن النمو والتغذية وتحمّل المجهود، ويقلل المخاطر طويلة الأمد لاضطرابات نظم القلب وارتفاع ضغط الشريان الرئوي وفشل القلب والسكتة الناتجة عن جلطات تعبر العيب وعدوى القلب أو الأوعية.",
