  "complete (toe clear)": "مكتمل (TOE خالٍ)",
  "complete accounting breakdown showing every patient invoice, tariff item, attending physician, and payer settlement.": "تفصيل محاسبي كامل يعرض كل فاتورة مريض وبند تعرفة والطبيب المعالج وتسوية الدافع.",
  "complete all sections fully and accurately. fields marked": "أكمل جميع الأقسام بالكامل وبدقة. الحقول المعلّمة بـ",
  "complete checklist": "إكمال قائمة التحقق",
  "complete detailed compilation of patient identity, address, and medical records. authorized medical utility only.": "تجميع مفصل كامل لهوية المريض وعنوانه وسجلاته الطبية. للاستخدام الطبي المصرّح به فقط.",
  "complete for a patient under 18, or who otherwise cannot consent for themselves. consent is given by a person with parental responsibility or legal guardian, in the patient's best interests.": "يُكمل لمريض دون 18 عامًا أو لا يستطيع منح الموافقة بنفسه لأي سبب آخر. يمنح الموافقةَ شخصٌ ذو مسؤولية أبوية أو ولي قانوني بما يحقق مصلحة المريض الفضلى.",
  "complete fully": "أكمل بالكامل",
  "complete huddle": "إكمال الاجتماع",
  "complete if the patient is a child. for infants and small children, consent is given by a parent or legal guardian (part l). weight-based prescribing, fluid and blood volumes are calculated and double-checked for the child's weight on the gsh paediatric weight-based calculation & safety worksheet, which is completed and counter-signed by the cardiac anaesthetist / intensivist before surgery.": "أكمل هذا الجزء إذا كان المريض طفلًا. للرضّع والأطفال الصغار، يمنح الموافقةَ أحدُ الوالدين أو الولي القانوني (الجزء L). تُحسب جرعات الأدوية وأحجام السوائل والدم حسب وزن الطفل ويُتحقق منها مرتين في ورقة GSH لحساب الجرعات حسب الوزن والسلامة للأطفال، والتي يكملها ويوقّع عليها طبيب تخدير القلب / أخصائي العناية المركزة قبل الجراحة.",
  "complete in sequential order": "أكمل بالترتيب",
  "complete record of all booked appointments across doctors and specializations.": "سجل كامل لجميع المواعيد المحجوزة حسب الأطباء والتخصصات.",
  "complete result": "إكمال النتيجة",
  "complete this part for every paediatric patient, and for any adult who cannot consent for themselves. consent is given by a person with parental responsibility or a legal guardian, in the patient's best interests. a young person assessed as competent (gillick) may also consent — record this in the notes.": "أكمل هذا الجزء لكل مريض من الأطفال، ولأي بالغ لا يستطيع منح الموافقة بنفسه. يمنح الموافقةَ شخصٌ ذو مسؤولية أبوية أو ولي قانوني بما يحقق مصلحة المريض الفضلى. ويجوز أيضًا للقاصر الذي يُقيَّم بأنه أهل للموافقة (معيار Gillick) أن يوافق — سجّل ذلك في الملاحظات.",
  "complete this section": "أكمل هذا القسم",
