  "each asd may be closed in one of three ways. the surgeon chooses during the operation, based on the number, size and position of the defects and the quality of the surrounding tissue. small or multiple defects are often closed by direct stitching; larger defects usually need a patch. please tick the options you consent to.": "يمكن إغلاق كل عيب في الحاجز الأذيني بإحدى ثلاث طرق. يختار الجرّاح أثناء العملية بناءً على عدد العيوب وحجمها وموضعها وجودة الأنسجة المحيطة. غالبًا ما تُغلق العيوب الصغيرة أو المتعددة بالخياطة المباشرة، بينما تحتاج العيوب الأكبر عادةً إلى رقعة. يرجى وضع علامة على الخيارات التي توافق عليها.",
