  "if not a parent — evidence of legal guardianship sighted": "إن لم يكن أحد الوالدين — تم الاطلاع على ما يثبت الولاية القانونية",
  "if retrieval is not possible or clinically contraindicated, the filter may become permanent. the patient and clinician should discuss this possibility prior to insertion.": "إذا تعذّر الاسترجاع أو كان ممنوعًا سريريًا، فقد يصبح المرشح دائمًا. وينبغي أن يناقش المريض والطبيب هذا الاحتمال قبل التركيب.",
  "if the duct is unusually large, calcified or fragile, the surgeon may need to close it from inside the pulmonary artery on bypass; this will be done only if necessary and in the patient's best interests.": "إذا كانت القناة كبيرة على غير المعتاد أو متكلسة أو هشة، فقد يحتاج الجرّاح إلى إغلاقها من داخل الشريان الرئوي أثناء المجازة؛ ولن يُجرى ذلك إلا عند الضرورة وبما يحقق مصلحة المريض الفضلى.",
  "if the mother lacks capacity to consent and immediate delivery is required in the best interests of mother or baby.": "إذا كانت الأم فاقدة للأهلية لمنح الموافقة وكانت الولادة الفورية مطلوبة لمصلحة الأم أو الطفل الفضلى.",
  "if the patient already signed a consent for this indication, link it instead of creating a new one.": "إذا وقّع المريض موافقة لهذه الدواعي مسبقًا، فاربطها بدلًا من إنشاء موافقة جديدة.",
  "if the patient wishes to withdraw consent before the procedure begins, complete this section": "إذا رغب المريض في سحب الموافقة قبل بدء الإجراء، فأكمل هذا القسم",
  "if you have a known contrast allergy, pre-medication may be administered prior to the procedure to reduce the risk of reaction.": "إذا كانت لديك حساسية معروفة لصبغة التباين، فقد تُعطى أدوية تحضيرية قبل الإجراء لتقليل خطر التفاعل.",
  "if you need to reschedule, please call the hospital records department at least 24 hours in advance.": "إذا احتجت إلى إعادة الجدولة، يرجى الاتصال بقسم السجلات قبل 24 ساعة على الأقل.",
