  "monitor liquid collection and verify hmo claim batches.": "متابعة التحصيل النقدي والتحقق من دفعات مطالبات التأمين.",
  "monitor type": "نوع جهاز المراقبة",
  "monitoring attached & alarms set before induction: spo₂, ecg, nibp (≤5-min), capnography, agent analyser, airway pressure. add temperature, quantitative nmt (tof) whenever a non-depolarising blocker is used, and depth-of-anaesthesia monitoring when tiva + nmb.": "تم توصيل أجهزة المراقبة وضبط الإنذارات قبل التحريض: تشبع الأكسجين، تخطيط القلب، الضغط غير الغازي (كل 5 دقائق أو أقل)، تخطيط ثاني أكسيد الكربون، محلل الغازات المخدرة، ضغط مجرى الهواء. أضف الحرارة، ومراقبة الإحصار العصبي العضلي الكمية (TOF) عند استخدام مرخٍ غير مزيل للاستقطاب، ومراقبة عمق التخدير عند استخدام TIVA مع المرخيات.",
