  "montgomery standard: the patient (or parent/guardian) must be told of any risk a reasonable person in their position would consider significant, and any risk significant to this particular patient. frequencies below are general; the clinician records the risks actually discussed. risks are generally higher in small infants.": "معيار Montgomery: يجب إبلاغ المريض (أو الوالد / ولي الأمر) بأي خطر قد يعدّه شخص عاقل في موقفه مهمًا، وبأي خطر مهم لهذا المريض تحديدًا. النسب أدناه عامة؛ ويسجّل الطبيب المخاطر التي نوقشت فعلًا. تكون المخاطر عمومًا أعلى لدى الرضّع الصغار.",
