  "removing the myxoma eliminates the source of fragments that can travel to the brain (stroke), limbs or organs, relieves or prevents obstruction of the nearby heart valve, and removes the risk of sudden death from the tumour. it establishes the diagnosis on laboratory examination.": "يزيل استئصال الورم المخاطي مصدر الأجزاء التي قد تنتقل إلى الدماغ (سكتة) أو الأطراف أو الأعضاء، ويخفف انسداد الصمام القلبي القريب أو يمنعه، ويزيل خطر الوفاة المفاجئة بسبب الورم. كما يُثبت التشخيص بالفحص المخبري.",
