  "surgical removal of a myxoma — a non-cancerous (benign) tumour growing inside an upper chamber of the heart (an atrium) — using open-heart surgery with the heart–lung (cardiopulmonary bypass) machine. a myxoma can shed fragments that travel in the blood (embolism) and can obstruct a heart valve; removal is the recommended treatment.": "الاستئصال الجراحي للورم المخاطي — وهو ورم غير سرطاني (حميد) ينمو داخل إحدى حجرتي القلب العلويتين (الأذين) — بجراحة قلب مفتوح باستخدام جهاز القلب والرئة (المجازة القلبية الرئوية). قد يُطلق الورم المخاطي أجزاء تنتقل في الدم (انصمام) وقد يسدّ صمامًا قلبيًا؛ والاستئصال هو العلاج الموصى به.",
