  "you (or your child's parent/guardian) have the right to make decisions about medical care and to refuse any procedure. you may withdraw consent at any time before the procedure begins. signing this form does not remove your legal rights. this form complies with the national health act 2014 (nigeria) and medbookie consent policy (gsh-t6).": "يحق لك (أو لوالد طفلك/ولي أمره) اتخاذ القرارات بشأن الرعاية الطبية ورفض أي إجراء. يمكنك سحب الموافقة في أي وقت قبل بدء الإجراء. التوقيع على هذا النموذج لا يُسقط حقوقك القانونية. يتوافق هذا النموذج مع قانون الصحة الوطني لعام 2014 (نيجيريا) وسياسة الموافقة في Medbookie (GSH-T6).",
  "you are about to manually bypass standard workflows and force this order to a": "أنت على وشك تجاوز سير العمل المعتاد يدويًا وفرض هذا الطلب إلى حالة",
  "you are now in edit mode.": "أنت الآن في وضع التعديل.",
  "you have the right to make decisions about your medical care and to refuse any procedure. if you wish to withdraw consent at any time before the procedure begins, you may do so. signing this form does not remove your legal rights. this form complies with the": "يحق لك اتخاذ القرارات بشأن رعايتك الطبية ورفض أي إجراء. إذا رغبت في سحب الموافقة في أي وقت قبل بدء الإجراء فيمكنك ذلك. التوقيع على هذا النموذج لا يُسقط حقوقك القانونية. يتوافق هذا النموذج مع",
  "you have the right to make decisions about your medical care and to refuse any procedure. if you wish to withdraw consent at any time before the procedure begins, you may do so. signing this form does not remove your legal rights. this form complies with the national health act 2014 (nigeria) and medbookie consent policy (gsh-t6).": "يحق لك اتخاذ القرارات بشأن رعايتك الطبية ورفض أي إجراء. إذا رغبت في سحب الموافقة في أي وقت قبل بدء الإجراء فيمكنك ذلك. التوقيع على هذا النموذج لا يُسقط حقوقك القانونية. يتوافق هذا النموذج مع قانون الصحة الوطني لعام 2014 (نيجيريا) وسياسة الموافقة في Medbookie (GSH-T6).",
